 <T>T main(Callable<T> action)throws Exception{FutureTask<T> t=new FutureTask<>(action);runOnMainSync(t);return t.get(10,TimeUnit.SECONDS);}
 void pause()throws Exception{Thread.sleep(180);waitForIdleSync();}
