 void formCases()throws Exception{
  Method form=method(source,"form",String.class,String.class,boolean.class);Class<?> type=getTargetContext().getClassLoader().loadClass("app.morphe.extension.chmate.PostLimitSource$Values");
  Object parsed=form.invoke(null,"bakusai","<form><input name=title maxlength=1></form><form method=post><input name=title maxlength=70><textarea name=body maxlength=2000 rows=99 data-maxlines=15></textarea></form>",true);
  ok(field(type,"title").getInt(parsed)==70&&field(type,"body").getInt(parsed)==2000&&field(type,"lines").getInt(parsed)==15,"posting form excludes search field and reads explicit caps");
  Object rows=form.invoke(null,"futaba","<form><textarea name=com rows=999 maxlength=1200></textarea></form>",false);ok(field(type,"lines").getInt(rows)==0&&field(type,"body").getInt(rows)==1200,"textarea rows are not a posting limit");
  Object known=form.invoke(null,"animanch","<form><textarea name=text></textarea></form>",true);ok(field(type,"title").getInt(known)==64&&field(type,"body").getInt(known)==1000&&field(type,"lines").getInt(known)==30,"existing Animanch creation limits retained when form omits them");
  ok("https://jbbs.shitaraba.net/bbs/api/setting.cgi/computer/45040/".equals(method(source,"address",String.class).invoke(null,"https://jbbs.shitaraba.net/computer/45040/")),"Shitaraba uses its public settings endpoint");
 }
 void edits()throws Exception{
  Config config=new Config();fixture(config,"https://example.invalid/post-limit-fixture/",true,true);
  main(()->{ok(spanStart(title)==6&&spanStart(body)==12,"real native counter identifies ASCII excess");ok(counter.getText().toString().contains("超過1バイト"),"remaining/overage shown");body.setSelection(3);return null;});pause();
  main(()->{ok(body.getSelectionStart()==3&&body.getText().toString().equals("1234567890123"),"counter preserves draft and cursor");config.body=1000;body.setText("a\nb\nc");return null;});pause();
  main(()->{ok(spanStart(body)==3&&counter.getText().toString().contains("3/2行"),"line cap uses native board setting times two: span="+spanStart(body)+" counter="+counter.getText());config.body=4;body.setText("ABCDE");return null;});pause();
  final ForegroundColorSpan foreign=new ForegroundColorSpan(0xff336699);
  main(()->{ok(spanStart(body)==4,"changed native board limit reflected");body.getText().setSpan(foreign,0,1,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);body.setSelection(2);prefs.edit().putBoolean("postEditorLimitDisplay",false).commit();return null;});pause();
  main(()->{ok(counter.getVisibility()==View.GONE&&spanStart(body)<0&&spanStart(title)<0,"OFF clears counter and only our highlights");ok(body.getText().toString().equals("ABCDE")&&body.getSelectionStart()==2&&body.getText().getSpanStart(foreign)==0,"OFF preserves input/cursor/unrelated styling");prefs.edit().putBoolean("postEditorLimitDisplay",true).commit();return null;});pause();
  main(()->{ok(counter.getVisibility()==View.VISIBLE&&spanStart(body)==4,"ON reapplies saved limits");dialog.dismiss();return null;});pause();
  main(()->{ok(spanStart(body)<0,"detaching releases styling");body.setText("ABCDEF");dialog.show();return null;});pause();main(()->{ok(spanStart(body)==4,"reattaching restores live display");return null;});
  Config unknown=new Config();unknown.title=unknown.body=unknown.lines=0;fixture(unknown,"https://example.invalid/unknown-limit-fixture/",false,true);
  main(()->{ok(counter.getText().toString().contains("上限未取得")&&!counter.getText().toString().contains("スレタイ")&&spanStart(body)<0&&spanStart(title)<0,"reply and unknown bounds never invent errors");return null;});
  String board="https://example.invalid/html-unit-fixture/";cached(board,true,values(2,3,0,true));fixture(unknown,board,true,false);
  main(()->{body.setText("a😀b");return null;});pause();main(()->{ok(spanStart(body)==3&&body.getText().toString().equals("a😀b"),"HTML UTF-16 limit never splits emoji");return null;});
 }
 void server()throws Exception{
  server=new ServerSocket();server.bind(new InetSocketAddress("127.0.0.1",0));serving=true;Thread thread=new Thread(()->{while(serving)try(Socket socket=server.accept()){
   BufferedReader input=new BufferedReader(new InputStreamReader(socket.getInputStream(),java.nio.charset.StandardCharsets.US_ASCII));String first=input.readLine(),line;while((line=input.readLine())!=null&&!line.isEmpty()){}if(first==null||!first.startsWith("GET /limits/SETTING.TXT "))throw new IOException("unexpected method/path");gets.incrementAndGet();byte[] data=("BBS_SUBJECT_COUNT=10\nBBS_MESSAGE_COUNT="+cap.get()+"\nBBS_LINE_NUMBER=1\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.write(data);out.flush();
  }catch(Exception e){if(serving)android.util.Log.w("PostLimitsTest","local server",e);}});thread.setDaemon(true);thread.start();
  Config unknown=new Config();unknown.title=unknown.body=unknown.lines=0;String board="http://127.0.0.1:"+server.getLocalPort()+"/limits/";keys.add(board+"\ntrue");fixture(unknown,board,true,false);main(()->{body.setText("ABCDEF");return null;});
  boolean loaded=false;for(int i=0;i<40&&!loaded;i++){Thread.sleep(100);loaded=main(()->counter.getText().toString().contains("/8バイト"));}ok(loaded&&gets.get()==1,"current SETTING.TXT fetched off main thread");
  cap.set(4);main(()->{ok(counter.performLongClick(),"counter long press requests current limits");return null;});boolean refreshed=false;for(int i=0;i<40&&!refreshed;i++){Thread.sleep(100);refreshed=main(()->counter.getText().toString().contains("/4バイト")&&spanStart(body)==4);}ok(refreshed&&gets.get()==2,"changed live board setting updates existing draft highlight");
  main(()->{ok(body.getText().toString().equals("ABCDEF"),"network refresh never rewrites draft");prefs.edit().putBoolean("postEditorLimitDisplay",false).commit();return null;});pause();main(()->{counter.performLongClick();return null;});Thread.sleep(200);ok(gets.get()==2,"OFF does not request settings");
 }
 String tree(View view){android.graphics.Rect r=new android.graphics.Rect();view.getLocalVisibleRect(r);StringBuilder text=new StringBuilder(view.getClass().getName()+" "+view.getWidth()+"x"+view.getHeight()+" visible="+view.getVisibility()+" rect="+r+" tag="+("haiagaru.post-limits".equals(view.getTag())?"LIMITS":"")+"\n");if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)text.append(tree(((ViewGroup)view).getChildAt(i)));return text.toString();}
 String nativeProbe()throws Exception{
  ActivityMonitor monitor=addMonitor("jp.syoboi.a2chMate.activity.ResEditActivity$Dialog",null,false);try{getTargetContext().startActivity(new Intent(Intent.ACTION_SENDTO,android.net.Uri.parse("http://127.0.0.1:9/test/read.cgi/android/1234567890/")).setClassName(getTargetContext().getPackageName(),"jp.syoboi.a2chMate.activity.ResEditActivity$Dialog").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));editor=waitForMonitorWithTimeout(monitor,12000);}finally{removeMonitor(monitor);}ok(editor!=null,"native editor opened");main(()->{editor.setShowWhenLocked(true);editor.setTurnScreenOn(true);return null;});Thread.sleep(1200);
  return main(()->{StringBuilder info=new StringBuilder(tree(editor.getWindow().getDecorView()));Map<?,?> all=(Map<?,?>)field(limits,"BINDINGS").get(null);info.append("bindings="+all.size()+"\n");for(Object ref:all.values()){Object value=((java.lang.ref.WeakReference<?>)ref).get();if(value!=null){View input=(View)field(value.getClass(),"body").get(value),row=(View)field(value.getClass(),"row").get(value);info.append("BODY PARENTS\n");for(View p=input;p!=null;p=p.getParent() instanceof View?(View)p.getParent():null)info.append(p.getClass().getName()+" h="+p.getHeight()+"\n");info.append("rowParent="+row.getParent()+" row="+(row instanceof TextView?((TextView)row).getText():"")+"\n");}}return info.toString();});
 }
 public void onCreate(Bundle args){super.onCreate(args);core=args!=null&&"true".equals(args.getString("core"));nativeOnly=args!=null&&"true".equals(args.getString("nativeOnly"));start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_OK;try{
  Context app=getTargetContext();ok(app.getPackageName().matches(".*\\.reporter(191|226|242)"),"isolated reporter only");ClassLoader loader=app.getClassLoader();limits=loader.loadClass("app.morphe.extension.chmate.PostEditorLimits");source=loader.loadClass("app.morphe.extension.chmate.PostLimitSource");excess=loader.loadClass("app.morphe.extension.chmate.PostEditorLimits$Excess");bind=method(limits,"bind",View.class,EditText.class,EditText.class,Object.class,String.class,String.class,boolean.class);
  prefs=app.getSharedPreferences("io.github.areteruhiro.chmate.haiagaru.ui-config",0);had=prefs.contains("postEditorLimitDisplay");enabled=prefs.getBoolean("postEditorLimitDisplay",true);prefs.edit().putBoolean("postEditorLimitDisplay",true).commit();host=startActivitySync(new Intent().setClassName(app.getPackageName(),"jp.syoboi.a2chMate.activity.HomeActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->{host.setShowWhenLocked(true);host.setTurnScreenOn(true);host.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);return null;});if(nativeOnly)result.putString("native",nativeProbe());else{if(!core)formCases();edits();server();}result.putString("result","PASS "+checks+" native-counter/highlight/toggle/live-limit checks; public posts=0");
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));code=Activity.RESULT_CANCELED;}finally{
  serving=false;try{if(server!=null)server.close();}catch(Exception ignored){}try{main(()->{if(editor!=null)editor.finish();if(dialog!=null)dialog.dismiss();if(host!=null)host.finish();return null;});}catch(Exception ignored){}if(prefs!=null){SharedPreferences.Editor edit=prefs.edit();if(had)edit.putBoolean("postEditorLimitDisplay",enabled);else edit.remove("postEditorLimitDisplay");edit.commit();}try{for(String key:keys)cache().remove(key);}catch(Exception ignored){}
 }finish(code,result);}
